"""Stage the ThinFlex tool directory for the full runtime ZIP, never a game DLL."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import stat
import struct

ROOT = Path(__file__).resolve().parents[1]
INPUT_DLL_SHA256 = "3f5f5b0f539e8ad22bcfc4381be41571257c0c29e8061057682f9b8525ca7b85"
OUTPUT_DLL_SHA256 = "03964dedcf8b7f4ebde24cd3d0738873d37c075a7a9b313dad001bb937f9d1b6"
# The output digest above was validated with this exact recipe. Revalidate it
# explicitly when changing the patcher; do not silently ship stale metadata.
PATCH_RECIPE_SHA256 = "ba009c7c97ceec8e049b8eb4e761e42bdea2d214fc155f7a37fe67f992814c3f"
SOURCE_FILES = (
    ("patch_studiorender_flex.py", "scripts/patch_studiorender_flex.py"),
    ("docs/THINFLEX-CRASH-FIX.md", "docs/THINFLEX-CRASH-FIX.md"),
    ("README.txt", "docs/THINFLEX-TEST-README.txt"),
    ("LICENSE", "LICENSE"),
)
PAYLOAD_FILES = ("ThinFlexPatch.exe",) + tuple(name for name, _ in SOURCE_FILES) + (
    "licenses/Python-LICENSE.txt", "licenses/PyInstaller-COPYING.txt", "licenses/EXE-NOTICES.txt",
)
TOOL_FILES = PAYLOAD_FILES + ("BUILD.json",)


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def _is_link(path):
    attributes = getattr(path.lstat(), "st_file_attributes", 0)
    return path.is_symlink() or bool(attributes & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0))


def _read_file(path):
    if _is_link(path):
        raise ValueError(f"Symlink inputs are not supported: {path}")
    data = path.read_bytes()
    if not data:
        raise ValueError(f"Empty package input: {path}")
    return data


def _validate_exe(data):
    if len(data) < 64 or data[:2] != b"MZ":
        raise ValueError("ThinFlexPatch.exe is not a PE executable")
    pe = struct.unpack_from("<I", data, 0x3C)[0]
    if pe < 64 or pe + 26 > len(data) or data[pe:pe + 4] != b"PE\0\0":
        raise ValueError("ThinFlexPatch.exe has an invalid PE header")
    machine, sections, _, _, _, optional_size, flags = struct.unpack_from("<HHIIIHH", data, pe + 4)
    magic = struct.unpack_from("<H", data, pe + 24)[0]
    if (machine, magic) not in ((0x14C, 0x10B), (0x8664, 0x20B)):
        raise ValueError("Expected an x86 or x64 Windows tool executable")
    if not sections or optional_size < 96 or pe + 24 + optional_size + 40 * sections > len(data):
        raise ValueError("ThinFlexPatch.exe has a truncated PE layout")
    if not flags & 2 or flags & 0x2000:
        raise ValueError("ThinFlexPatch.exe must be an executable, not a DLL")


def read_tool_directory(source):
    """Validate a fixed tool inventory and return the same bytes to be archived."""
    source = Path(source)
    if not source.is_dir() or _is_link(source):
        raise ValueError("Missing or linked ThinFlex tool directory")
    allowed_directories = {str(Path(name).parent).replace("\\", "/") for name in TOOL_FILES} - {"."}
    found = set()
    directories = [source]
    while directories:
        for path in directories.pop().iterdir():
            name = path.relative_to(source).as_posix()
            if _is_link(path):
                raise ValueError(f"Linked tool inputs are not supported: {name}")
            if path.is_dir() and name in allowed_directories:
                directories.append(path)
            elif path.is_file() and name in TOOL_FILES:
                found.add(name)
            else:
                raise ValueError(f"Unexpected ThinFlex tool entry: {name}")
    if found != set(TOOL_FILES):
        raise ValueError(f"Missing ThinFlex tool files: {', '.join(sorted(set(TOOL_FILES) - found))}")
    files = {name: _read_file(source / name) for name in TOOL_FILES}
    _validate_exe(files["ThinFlexPatch.exe"])
    if sha256(files["patch_studiorender_flex.py"].replace(b"\r\n", b"\n")) != PATCH_RECIPE_SHA256:
        raise ValueError("Patch recipe changed; revalidate the pinned output DLL digest before packaging")
    metadata = json.loads(files["BUILD.json"])
    if not isinstance(metadata, dict) or metadata.get("format_version") != 1:
        raise ValueError("Invalid ThinFlex BUILD.json format")
    expected_hashes = {name: sha256(files[name]) for name in PAYLOAD_FILES}
    if metadata.get("sha256") != expected_hashes:
        raise ValueError("ThinFlex BUILD.json payload hashes do not match the exact tool inventory")
    if (metadata.get("game_dll_included") is not False
            or metadata.get("automatic_installation") is not False
            or metadata.get("input_dll_sha256") != INPUT_DLL_SHA256
            or metadata.get("output_dll_sha256") != OUTPUT_DLL_SHA256):
        raise ValueError("ThinFlex BUILD.json does not match the validated manual patch recipe")
    return files


def package(exe, output, *, version, recipe_commit, run_id, python_license, pyinstaller_license, root=ROOT):
    exe, output, root = map(Path, (exe, output, root))
    if exe.name != "ThinFlexPatch.exe":
        raise ValueError("Expected the explicitly built ThinFlexPatch.exe")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9.+_-]*", version):
        raise ValueError("Invalid version")
    if not re.fullmatch(r"[0-9a-f]{40}", recipe_commit):
        raise ValueError("recipe_commit must be a full lowercase Git commit SHA")
    run_id = str(run_id)
    if not re.fullmatch(r"[1-9][0-9]*", run_id):
        raise ValueError("run_id must be a positive GitHub Actions run ID")
    if (root / "VERSION").read_text(encoding="utf-8").strip() != version:
        raise ValueError("Package version differs from the repository VERSION")

    # Only these explicit inputs can enter the tool directory.
    files = {"ThinFlexPatch.exe": _read_file(exe)}
    _validate_exe(files["ThinFlexPatch.exe"])
    for archive_name, relative in SOURCE_FILES:
        files[archive_name] = _read_file(root / relative)
    files["licenses/Python-LICENSE.txt"] = _read_file(Path(python_license))
    files["licenses/PyInstaller-COPYING.txt"] = _read_file(Path(pyinstaller_license))
    files["licenses/EXE-NOTICES.txt"] = (
        "ThinFlexPatch.exe bundles CPython and the PyInstaller bootloader.\n"
        "CPython license: Python-LICENSE.txt.\n"
        "PyInstaller license and bootloader exception: PyInstaller-COPYING.txt.\n"
        "The independently written patch tool source is covered by ../LICENSE.\n"
        "No game DLL or game implementation source is included.\n"
    ).encode("utf-8")
    recipe_bytes = files["patch_studiorender_flex.py"]
    if sha256(recipe_bytes.replace(b"\r\n", b"\n")) != PATCH_RECIPE_SHA256:
        raise ValueError("Patch recipe changed; revalidate the pinned output DLL digest before packaging")
    metadata = {
        "format_version": 1,
        "version": version,
        "recipe_commit": recipe_commit,
        "run_id": run_id,
        "experimental": True,
        "input_dll_sha256": INPUT_DLL_SHA256,
        "output_dll_sha256": OUTPUT_DLL_SHA256,
        "signature_invalid": True,
        "game_validated": False,
        "automatic_installation": False,
        "game_dll_included": False,
        "sha256": {name: sha256(data) for name, data in files.items()},
    }
    files["BUILD.json"] = (json.dumps(metadata, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    if output.exists() or output.is_symlink():
        raise FileExistsError(f"Refusing to overwrite existing output: {output}")
    output.parent.mkdir(parents=True, exist_ok=True)
    # The exclusive directory creation preserves a competing output as well.
    output.mkdir()
    created_files = []
    created_directories = [output]
    try:
        for name, data in files.items():
            destination = output / name
            if not destination.parent.exists():
                destination.parent.mkdir()
                created_directories.append(destination.parent)
            with destination.open("xb") as handle:
                created_files.append(destination)
                handle.write(data)
        if read_tool_directory(output) != files:
            raise ValueError("Tool directory integrity verification failed")
    except BaseException:
        # Remove only files/directories created by this call, never a competing
        # output or an unrecognized file inserted into the directory.
        for destination in reversed(created_files):
            destination.unlink(missing_ok=True)
        for directory in reversed(created_directories):
            try:
                directory.rmdir()
            except OSError:
                pass
        raise
    return metadata


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--exe", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--version", required=True)
    parser.add_argument("--recipe-commit", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--python-license", type=Path, required=True)
    parser.add_argument("--pyinstaller-license", type=Path, required=True)
    args = parser.parse_args()
    try:
        package(args.exe, args.output_dir, version=args.version, recipe_commit=args.recipe_commit,
                run_id=args.run_id, python_license=args.python_license, pyinstaller_license=args.pyinstaller_license)
    except (OSError, ValueError, struct.error) as error:
        parser.exit(1, f"Rejected: {error}\n")
    print(f"ThinFlex tool directory for the full runtime ZIP: {args.output_dir}")
    print("Game DLL is not included; this build was not game-tested; installation is manual.")


if __name__ == "__main__":
    main()
